#[test]
fn sqrt_f32() {
    let f: fn(f32) -> f32 = |x| x.sqrt();
    let t = simd128();
    check_fixed_un::<f32, f32, 4>(|a| t.sqrt_f32x4(a), |a, o| map_un(a, o, f), "sqrt_f32x4");
    check_un::<f32, f32>(
        |a, o| t.sqrt_f32_slice(a, o),
        |a, o| map_un(a, o, f),
        "sqrt_f32_slice",
    );
}

